locked.scoped_css:
@scope (.slide[data-layout-id="paper-ink.nonrelationship.M1"]) {
canvas.scene { position: absolute; inset: 0; z-index: 1; }
  svg.overlay { position: absolute; inset: 0; z-index: 2; pointer-events: none; }

  /* 方块上方：对照行 */
  .compare {
    position: absolute; left: 0; right: 0; top: 326px;
    display: flex; align-items: center; justify-content: center;
    gap: var(--space-5); z-index: 3;
    font-family: var(--sans); font-weight: 300;
    font-size: var(--type-subheading); color: var(--ink-70);
    letter-spacing: .06em;
  }
  .compare .arr { font-style: normal; color: var(--ink-45); }
  .compare .sep { width: 1px; height: 26px; background: var(--ink-25); margin: 0 var(--space-6); }
  .compare .q {
    font-family: var(--serif); font-size: var(--type-heading);
    color: var(--ink); transform: translateY(2px);
  }
  /* 方块刻字（纸色反色） */
  .boxtext {
    position: absolute; z-index: 3;
    display: flex; flex-direction: column;
    align-items: center; justify-content: center;
    color: var(--paper); pointer-events: none;
  }
  .boxtext .t1 {
    font-family: var(--mono); font-size: var(--type-emphasis);
    letter-spacing: .16em; text-indent: .16em;
  }
  .boxtext .divi {
    width: 140px; height: 1px;
    background: color-mix(in srgb, var(--paper) 55%, transparent);
    margin: var(--space-6) 0 var(--space-5);
  }
  .boxtext .t2 {
    font-family: var(--mono); font-size: var(--type-meta);
    letter-spacing: .4em; text-indent: .4em;
    color: color-mix(in srgb, var(--paper) 80%, transparent);
  }
}
